// Base — the shipped APH_ACT_SCHEDULING family (excerpted: one of its
// thirteen labels, and its real floors).
classifiers "APH_ACT_SCHEDULING" {
  description = "Classifies what a message does to a calendar commitment between two parties"
  labels {
    TIME_ACCEPTED {
      description = "Accepts a specific time the counterparty previously proposed, converting that proposal into a firm commitment for the sender's principal."
      examples    = ["Tuesday at 2pm works — I'm booking it.",
                     "Accept the meeting time as proposed.",
                     "Yes, Thursday 10:00 Eastern is confirmed on my side."]
    }
  }
  escalate t0_signals   >= 940
  escalate t1_embedding >= 860
}

// Overlay — a LATER entry for the SAME namespace, contributed by anyone.
// Adds a label the base does not define. This is legal and is the ONE
// additive direction in the lattice.
classifiers "APH_ACT_SCHEDULING" {
  labels {
    ACCEPT_WITH_TRAVEL_BUFFER {
      description = "Accepts the proposed time but asserts a required buffer before or after"
      examples    = ["works if we can start 15 minutes late",
                     "yes, but I need a half hour after for travel",
                     "fine, just not back-to-back with the prior call"]
    }
  }
}
